use core::{convert::Infallible, fmt::Debug};

use dilithia_serialization::{
    DecoderInput, SerializationError, decode_bool, decode_exact, decode_option, decode_uleb128_u64,
    encode_bool, encode_option, encode_uleb128_u64,
};

// Exercise arbitrary wire inputs, including rejected inputs, rather than only
// starting from values generated by the encoder. The surrounding bytes must
// never complete a truncated value or count as trailing data inside the window.
fn check_boundaries<T: Debug + PartialEq>(
    bytes: &[u8],
    decode: fn(&mut dyn DecoderInput) -> Result<T, SerializationError>,
    encode: impl FnOnce(T) -> Vec<u8>,
) {
    let mut backing = vec![0xff];
    backing.extend_from_slice(bytes);
    backing.extend_from_slice(&[0x01, 0x00]);
    let source = &backing[1..1 + bytes.len()];
    let mut prefix = source;
    let mut exact = source;
    let decoded = decode(&mut prefix);
    let complete = decode_exact(&mut exact, decode);

    match decoded {
        Ok(value) => {
            let consumed = source.len() - prefix.len();
            assert!(core::ptr::eq(prefix, &source[consumed..]));
            if prefix.is_empty() {
                assert_eq!(complete.as_ref(), Ok(&value), "{bytes:02x?}");
                assert!(core::ptr::eq(exact, &source[source.len()..]));
            } else {
                assert_eq!(complete, Err(SerializationError::TrailingBytes));
                assert!(core::ptr::eq(exact, source));
            }
            assert_eq!(encode(value), source[..consumed], "{bytes:02x?}");
        }
        Err(error) => {
            assert!(core::ptr::eq(prefix, source));
            assert_eq!(complete, Err(error), "{bytes:02x?}");
            assert!(core::ptr::eq(exact, source));
        }
    }
}

#[test]
fn every_short_uleb128_input_obeys_canonical_and_source_boundaries() {
    check_boundaries(&[], decode_uleb128_u64, encode_uleb128_u64);
    for first in 0..=u8::MAX {
        check_boundaries(&[first], decode_uleb128_u64, encode_uleb128_u64);
        for second in 0..=u8::MAX {
            check_boundaries(&[first, second], decode_uleb128_u64, encode_uleb128_u64);
        }
    }
}

#[test]
fn nested_option_bool_accepts_only_its_four_canonical_prefixes() {
    fn decode(input: &mut dyn DecoderInput) -> Result<Option<Option<bool>>, SerializationError> {
        decode_option(input, |cursor| decode_option(cursor, decode_bool))
    }

    fn encode(value: Option<Option<bool>>) -> Vec<u8> {
        encode_option(value, |inner| {
            encode_option(inner, |value| Ok::<_, Infallible>(encode_bool(value)))
        })
        .unwrap()
    }

    // These are all values of Option<Option<Bool>>, not a sampling limit.
    let canonical = [
        (&[0x00][..], None),
        (&[0x01, 0x00][..], Some(None)),
        (&[0x01, 0x01, 0x00][..], Some(Some(false))),
        (&[0x01, 0x01, 0x01][..], Some(Some(true))),
    ];
    let check = |bytes: &[u8]| {
        check_boundaries(bytes, decode, encode);
        let expected = canonical
            .iter()
            .find(|(prefix, _)| bytes.starts_with(prefix));
        let mut input = bytes;
        let result = decode(&mut input);
        match expected {
            Some((prefix, value)) => {
                assert_eq!(result, Ok(*value));
                assert!(core::ptr::eq(input, &bytes[prefix.len()..]));
            }
            None => assert!(result.is_err(), "{bytes:02x?}"),
        }
    };

    check(&[]);
    for first in 0..=u8::MAX {
        check(&[first]);
        for second in 0..=u8::MAX {
            check(&[first, second]);
        }
        // Enumerate every possible Bool byte once both Some tags are present.
        check(&[0x01, 0x01, first]);
        for (prefix, _) in canonical {
            let mut with_suffix = prefix.to_vec();
            with_suffix.push(first);
            check(&with_suffix);
        }
    }
}
